/** 169 캐노니컬 핸드 순서 — equity169/nash 생성기와 동일 (hi 12..0, lo hi..0, 페어→수딧→오프수트) */
export const HAND_ORDER: string[] = (() => {
  const R = ['2','3','4','5','6','7','8','9','T','J','Q','K','A'];
  const out: string[] = [];
  for (let hi = 12; hi >= 0; hi--) for (let lo = hi; lo >= 0; lo--) {
    if (hi === lo) out.push(R[hi] + R[lo]);
    else { out.push(R[hi] + R[lo] + 's'); out.push(R[hi] + R[lo] + 'o'); }
  }
  return out;
})();

const decode = (s: string | undefined): Float32Array => {
  const f = new Float32Array(169);
  if (s) for (let i = 0; i < 169; i++) f[i] = Number(s[i]) / 8;
  return f;
};

export type NashKind = 'shove' | 'callBB' | 'callSB';

/** 🔴 **격리 구간 — 빅 앤티 2~10BB 의 k≥2 열.** 화면·드릴·스팟 분석 어디에도 내보내지 않는다.
 *
 *  ── 이력 ──
 *  2026-09-17: 빅앤티 4~6BB 의 k≥2 가 **뒤집혀 있었다**(9맥스 UTG 가 SB 보다 넓다 — 실측 4bb k1=71.5 k2=75.9 k8=74.9 ·
 *    6bb k1=64.6 k8=65.5). 같은 표가 **9맥스 UTG 6BB 에서 K2o·22 를 100% 올인**이라 말했고 화면은 그걸
 *    `chart_nash`(최고 신뢰 등급)로 내보냈다. 손익분기 역산으로 교차 확인(3BB UTG 46.2% vs SB 38.5%).
 *  2026-09-19 재산출로 **2~10BB 전체로 넓혔다.** 4~6BB 만의 문제가 아니었다 — 이 데이터의 모델은
 *    **단일 콜러 근사**(첫 콜러와 헤즈업, 뒤는 접는다)인데 얕을수록 그 가정이 깨진다.
 *    `P(2명 이상 콜)` 실측(k=8): 7bb **47.7%** · 10bb **17.9%** · 12bb **11.8%**. 검증된 노앤티 7bb 가 13.5% 라
 *    **12bb 가 같은 신뢰도 지점**이고, 그 아래는 오차가 '실제보다 넓게'(더 공격적으로) 쏠린다 — 해로운 방향이다.
 *    ⚠ 그래서 **빅앤티 10bb 의 BB 콜이 다시 빈칸이 된다**(그동안 떠 있던 값이 실제의 2.4배였다).
 *    **틀린 값보다 빈칸이 낫다** — **오너 승인(2026-09-19)**. 화면에서 63칸이 내려가는 것은
 *    CLAUDE.md 3번(기능·데이터 보존)에 걸려 오너 확인을 받은 결정이다. 되돌릴지 판단할 사람은 이 출처를 봐라.
 *  k=1(SB)은 상대가 **하나뿐**이라 단일 콜러 근사가 근사가 아니라 정확하다. 그래서 k=1 은 전 깊이 살린다.
 *
 *  ⚠ 되살리려면 **데이터를 고친 뒤** 이 목록에서 그 깊이를 빼라. 목록만 비우면 같은 거짓 조언이 그대로 돌아온다.
 *  `ranges.test.ts` 의 k 단조성·**스택 단조성** 계약이 그때 진짜인지 판정해 준다. */
export const NASH_ANTE_QUARANTINE: readonly number[] = [2, 3, 4, 5, 6, 7, 8, 9, 10];

/** 🔴 **추정 구간 — 위 격리 구간(빅 앤티 2~10BB · k≥2)에 2026-09-21 다인 콜 근사 값을 채웠다.**
 *  오너 결정 2026-09-21 "근사 계산 — 오늘 안에"(정확 계산은 3인 에퀴티 169³ 산출이 하루 단위라 미룸).
 *  산출: `scripts/gen-nash/solve-multi.mjs` — 두 번째 콜러(오버콜)까지 보고, 3인 에퀴티는 2인 곱 정규화 근사.
 *  단일 콜러 근사가 '실제보다 넓게' 틀리던 방향을 줄이지만 **정확값이 아니다** — 12bb 이상과 등급이 다르다.
 *  · `isNashQuarantined` 는 그대로 true 다: 드릴(preflopQuiz)·스팟 분석(spotEvaluate)은 추정값으로 채점하지 않는다.
 *  · 차트만 `allowApprox=true`(hasNashRange/nashRange 5번째 인자)로 읽고 '추정' 배지를 단다.
 *  · 이 목록에서 깊이를 빼면 그 깊이는 다시 빈칸(격리)이다. 진짜 3인 에퀴티로 재산출하면 격리·추정 목록에서 **함께** 빼라. */
export const NASH_ANTE_APPROX: readonly number[] = [2, 3, 4, 5, 6, 7, 8, 9, 10];
/** 이 조합이 '추정'(다인 콜 근사) 값인가 — 빅앤티 · k≥2 · NASH_ANTE_APPROX 깊이. k 를 모르면 추정이라고 말하지 않는다. */
export function isNashApprox(stack: number, ante: boolean, k?: number): boolean {
  return ante && k !== undefined && k >= 2 && NASH_ANTE_APPROX.includes(stack);
}

/** 🔴 **BB 콜 표 전용 격리 — 노앤티 3BB 의 k≥2 열**(2026-09-19 감사, 셔브 표와 같은 방법).
 *
 *  무엇이 틀렸나: 상대가 좁고 강한 레인지로 셔브할수록(k↑) BB 의 콜 레인지는 좁아야 하는데, 노앤티 3bb 는
 *  **SB 셔브보다 BTN 셔브에 더 넓게 콜**한다(k1=93.6 → k2=**99.2**). 노앤티 k≥2 는 2026-09-19 재산출 대상이
 *  아니어서(위 머리말 ②) 옛 값 그대로이고, 이 칸만 kind 별로 막는다 — kind 를 구분하지 않으면 같은 깊이의
 *  정상 셔브·SB 콜 표까지 같이 가려진다.
 *
 *  ⚠ 여기 있던 **빅앤티 7·8·9BB 는 뺐다**(2026-09-19): 그 깊이는 이제 `NASH_ANTE_QUARANTINE`(빅앤티 2~10BB)이
 *    kind 를 가리지 않고 통째로 막는다. 여기 남겨 두면 같은 깊이를 두 목록이 말해 다음 편집이 어느 쪽을 믿을지 모른다.
 *  ⚠ 되살리려면 표를 다시 만든 뒤 이 목록을 비우고 `ranges.test.ts` 의 콜 표 단조성 계약이 판정하게 해라. */
export const NASH_CALLBB_QUARANTINE: { readonly ante: readonly number[]; readonly no: readonly number[] } = { ante: [], no: [3] };

/** 이 조합이 격리 구간인가. 소비자 셋(차트·드릴·스팟 분석)이 **같은 판정**을 쓰게 하는 단 하나의 함수다.
 *
 *  🔴 **k(뒤에 남은 인원)를 함께 본다 — 막는 것은 k≥2 열이고 k=1(SB)은 전 깊이 살아 있다.**
 *  2026-09-17 1차 판단은 "2~3BB 는 데드머니가 커서 any-two 잼이 정상" 이었는데 **역산으로 반증됐다**:
 *    UTG(k=8) 손익분기 = S/(0.5+2S) → 2BB **44.4%** · 3BB **46.2%** · S→∞ 50% 로 **단조 증가**한다.
 *    즉 어떤 스택에서도 44.4% 밑으로 내려가지 않는다. 그런데 앱 엔진 실측 승률은
 *    32o 32.5% · 82o 36.9% · 93o 40.2% 로 전부 그 아래인데 표는 **UTG 100% 잼**이라고 말했다.
 *    빅 앤티도 이 결론을 못 뒤집는다 — 앤티 1BB 는 데드머니(1.5→2.5)만 키우고 분모의 `2S` 를 못 건드린다.
 *  SB(k=1) 임계는 `(S−0.5)/(2S)` → 2BB 37.5% · 3BB 41.7% 로 낮다.
 *  ⚠ 2026-09-19 정정: 예전에 여기 "**옛** SB 열은 그 임계와 정합하니 맞다"(빅앤티 2BB 91.9%) 고 적혀 있었는데
 *    그건 **미증명이었고 실제로 좁았다**. 옛 빅앤티 SB 열은 이 모델보다 8~16%p 좁고(7bb 62.4 vs 77.3 ·
 *    20bb 48.5 vs 53.5), 6→7bb 에서 스택이 줄었는데 넓어지지도 않았다. k=1 열은 **전부 새 값으로 바꿨다** —
 *    지금 살아 있는 근거는 "옛 표가 맞다" 가 아니라 "**k=1 은 상대가 하나뿐이라 단일 콜러 근사가 정확하다**" 이고,
 *    같은 모델이 옛 **노앤티** k=1 을 평균 0.6%p 로 되살린 것이 그 증거다.
 *  ⚠ k 를 안 넘기면(예전 호출부) 보수적으로 **격리로 본다** — 모르면 덜 말하는 쪽이 안전하다. */
export function isNashQuarantined(stack: number, ante: boolean, k?: number, kind: NashKind = 'shove'): boolean {
  const brokenColumn = k === undefined || k >= 2;   // 모르면 보수적으로 격리 — '모르면 덜 말한다'
  if (kind === 'callBB' && (ante ? NASH_CALLBB_QUARANTINE.ante : NASH_CALLBB_QUARANTINE.no).includes(stack) && brokenColumn) return true;
  if (!ante || !NASH_ANTE_QUARANTINE.includes(stack)) return false;
  return brokenColumn;
}

const tableOf = (kind: NashKind, k: number, stack: number, ante: boolean, allowApprox = false): string | undefined =>
  (isNashQuarantined(stack, ante, k, kind) && !(allowApprox && isNashApprox(stack, ante, k))) ? undefined
    : (kind === 'shove' ? SHOVE : kind === 'callBB' ? CALL_BB : CALL_SB)[ante ? 'ante' : 'no']?.[String(k)]?.[String(stack)];

/** 그 조합의 표가 실제로 있는가. 없는 조합을 nashRange 로 읽으면 전부 0(=전부 폴드)이라 **틀린 조언이 된다** —
 *  화면은 이걸로 먼저 걸러 "데이터 없음"을 정직하게 보여야 한다(가까운 깊이로 몰래 대체하지 않는다). */
export function hasNashRange(kind: NashKind, k: number, stack: number, ante: boolean, allowApprox = false): boolean {
  return tableOf(kind, k, stack, ante, allowApprox) !== undefined;
}

/** k(뒤 인원)·스택(bb)·앤티 여부로 169핸드 빈도(0..1)를 돌려준다. callSB 는 k>=2 전용. */
/** `allowApprox` — 차트 전용. 추정 구간(NASH_ANTE_APPROX)의 다인 콜 근사 표까지 돌려준다. 드릴·스팟은 넘기지 마라. */
export function nashRange(kind: NashKind, k: number, stack: number, ante: boolean, allowApprox = false): Float32Array {
  return decode(tableOf(kind, k, stack, ante, allowApprox));
}
